using (var scope = app.Services.CreateScope())
{
    var trainer = scope.ServiceProvider.GetRequiredService<TicketModelTrainer>();
    var metrics = trainer.TrainAndSave(dataPath, modelPath);
    app.Logger.LogInformation("Training complete: {Metrics}", metrics);
}

app.MapControllers();
app.Run();

